import java.util.zip.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;public class Audit{public static void main(String[]a)throws Exception{try(var z=new ZipFile(a[0])){var c=new ClassNode();new ClassReader(z.getInputStream(z.getEntry("local/lito381/server/ClientSession.class"))).accept(c,0);for(var m:c.methods)if(java.util.Set.of("battleWalkAction","useSourceWeapon","useFoeSlayerSpell","broadcastWieldState").contains(m.name)){System.out.println(m.name+m.desc);for(var n:m.instructions)if(n instanceof MethodInsnNode x)System.out.println("CALL "+x.owner+" "+x.name+x.desc);}}}}